"4-Achs-Sätze mit X/Y/Z und A zusammen: Viele Steuerungen rechnen dort Grad wie Millimeter, der Fräser läuft dann am Werkstück zu langsam oder zu schnell. „Umgerechnet“ schreibt den F-Wert so, dass eine solche Steuerung den gewünschten Vorschub an der Schneide fährt. „Zeitreziprok“ schaltet auf G93 und gibt in jedem Satz 1/Zeit an – eindeutig, wenn die Steuerung G93 kennt.":"Blocos de 4 eixos com X/Y/Z e A juntos: muitos comandos contam ali os graus como milímetros, e a fresa avança então devagar ou rápido demais na peça. “Convertido” escreve o valor F de modo que um comando desse tipo execute o avanço desejado na aresta de corte. “Tempo inverso” muda para G93 e informa 1/tempo em cada bloco – inequívoco se o comando conhece G93.",
