"Alle Biegungen mit Winkel, Radius, K-Faktor, Zugabe, Länge und Presskraft als Tabelle für die Abkantpresse":"Todas as dobras com ângulo, raio, fator K, tolerância, comprimento e força de prensagem em uma tabela para a dobradeira",
"Alle Einstellungen, Symbolleisten-Anpassungen und eigenen Tastenkürzel auf die Vorgaben zurücksetzen?\n\nEigene Werkzeugbibliotheken, Materialien und Vorlagen bleiben erhalten.":"Redefinir todas as preferências, personalizações da barra de ferramentas e atalhos de teclado próprios para os padrões?\n\nBibliotecas de ferramentas, materiais e modelos próprios são mantidos.",
"Alle Flächen des Merkmals wählen: bei einer Bohrung die Wand (und Senkung, Boden), bei einer Tasche Wände und Boden, bei einem Zapfen Mantel und Stirnfläche. Das Merkmal wandert um X/Y/Z; die alte Stelle wird geschlossen. Geht auch bei importierten STEP-Teilen ohne Verlauf. Beim ersten Mal lädt der große Geometriekern (einige Sekunden).":"Selecione todas as faces do recurso: em um furo a parede (e o rebaixo, o fundo), em uma cavidade as paredes e o fundo, em um ressalto a lateral e a face frontal. O recurso se desloca em X/Y/Z; o local antigo é fechado. Funciona também em peças STEP importadas sem histórico. Na primeira vez, o kernel geométrico grande é carregado (alguns segundos).",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Selecione todas as faces que devem desaparecer (em uma cavidade, paredes e fundo; em um furo, a parede; em uma concordância, a face arredondada). As faces vizinhas são estendidas sobre a lacuna. A etapa é recalculada quando o corpo muda; na primeira vez, o núcleo geométrico completo é carregado para isso (alguns segundos).",
