"Dieser Browser kann keinen Ordner als Speicherort verwenden – in der WerkFab-App, in Chrome oder in Edge geht es.":"Este navegador não pode usar uma pasta como local de armazenamento – isso funciona no aplicativo WerkFab, no Chrome ou no Edge.",
"Dieser Browser unterstützt keine SpaceMouse (WebHID). Bitte Chrome, Edge oder die Desktop-App verwenden.":"Este navegador não oferece suporte a SpaceMouse (WebHID). Use o Chrome, o Edge ou o aplicativo desktop.",
