"Drehen: C-Achse und angetriebenes Werkzeug ein":"Torneamento: eixo C e ferramenta motorizada ligados",
"Drehen: Das Teil muss rotationssymmetrisch um die Z-Achse liegen. Z0 = Planfläche oben, X = Durchmesser.":"Torneamento: a peça deve ser simétrica em rotação em torno do eixo Z. Z0 = face frontal no topo, X = diâmetro.",
"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Girar: clique no ponto de rotação e depois indique o ângulo com o mouse (pré-visualização). Esc encerra.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Torneamento: diâmetro em que a torre indexa (Okuma, LinuxCNC). 0 = Ø do bruto + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Girar: selecione elementos, clique no ponto de rotação e indique o ângulo com o mouse (pré-visualização); também como cópia",
"Drehen: Gewindeschnitt":"Torneamento: passe de rosca",
"Drehen: Gewindezyklus":"Torneamento: ciclo de rosca",
"Drehen: Polar-Interpolation aus":"Torneamento: interpolação polar desligada",
"Drehen: Polar-Interpolation ein (X Durchmesser, C in mm; leer = X/C in Grad)":"Torneamento: interpolação polar ligada (X diâmetro, C em mm; vazio = X/C em graus)",
"Drehen: Schlichtzyklus (Kontur des Schruppzyklus)":"Torneamento: ciclo de acabamento (contorno do ciclo de desbaste)",
"Drehen: Schruppzyklus ({contour} = Konturzeilen)":"Torneamento: ciclo de desbaste ({contour} = linhas do contorno)",
"Drehen: Vorsatz erste Konturzeile":"Torneamento: prefixo da primeira linha do contorno",
"Drehen: Vorsatz letzte Konturzeile":"Torneamento: prefixo da última linha do contorno",
"Drehen: Y-Achse aus":"Torneamento: eixo Y desligado",
"Drehen: Y-Achse ein (Ebene X/Y; hier auch die C-Klemmung der Maschine eintragen)":"Torneamento: eixo Y ligado (plano X/Y; informe aqui também o travamento C da máquina)",
"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Torneamento: Z à frente da face em que a torre indexa. 0 = distância de segurança + 100 mm",
"Drehen: Zylinder-Interpolation aus":"Torneamento: interpolação cilíndrica desligada",
"Drehen: Zylinder-Interpolation ein ({cylr} = Radius; leer = Z/C ohne)":"Torneamento: interpolação cilíndrica ligada ({cylr} = raio; vazio = Z/C sem)",
"Drehen: angetriebenes Werkzeug und C-Achse aus":"Torneamento: ferramenta motorizada e eixo C desligados",
"Drehen: einen Winkel angeben.":"Girar: informe um ângulo.",
"Drehendes Teil in einer Wendel oder in Längsbahnen schlichten":"Acabar uma peça em rotação em hélice ou em passagens longitudinais",
