"Eilgangbewegungen beibehalten":"Manter movimentos rápidos",
"Eilgangrückzug zulassen":"Permitir recuo em rápido",
"Eilgangweg":"Percurso em avanço rápido",
"Ein Fusion-Design mit seiner Zeitachse übernehmen: über das Export-Skript für Fusion":"Importar um projeto do Fusion com sua linha do tempo: pelo script de exportação para o Fusion",
"Ein Gelenk anlegen: ZUSAMMENBAU → „Gelenk“ (J), erst das bewegliche Teil, dann das feste anklicken, Art „Drehgelenk“ oder „Schiebegelenk“.":"Criar uma junta: MONTAGEM → “Junta” (J), clique primeiro na peça móvel, depois na fixa, tipo “Junta de revolução” ou “Junta deslizante”.",
"Ein Rechteck zeichnen: Werkzeug „Rechteck“ (R), zwei Ecken anklicken. Maße kann man direkt eintippen, z. B. 80 und 50.":"Desenhar um retângulo: ferramenta “Retângulo” (R), clique em dois cantos. As cotas podem ser digitadas diretamente, p. ex. 80 e 50.",
"Ein Rechtsklick in einen Dialog (nicht in ein Eingabefeld) drückt dessen OK-Schaltfläche":"Um clique direito em uma caixa de diálogo (fora de um campo de entrada) aciona o botão OK",
"Ein anderes gespeichertes Design als Komponente einfügen":"Inserir outro projeto salvo como componente",
"Ein eingefügter Satz verschiebt alle folgenden Satznummern – so zählen sie nicht als Änderung":"Um bloco inserido desloca todos os números de bloco seguintes – assim eles não contam como alteração",
"Ein fertiges Teil mit Konstruktion und Fräsbearbeitung":"Uma peça pronta com projeto e fresamento",
"Ein gerollter Rand über 350° schließt sich zum Rohr – das ist so nicht herstellbar":"Uma borda enrolada acima de 350° se fecha em um tubo – assim não é possível fabricar",
"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Converter uma malha fechada em um corpo sólido (cada triângulo vira uma face)",
"Ein leeres Design beginnen":"Começar um design vazio",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Uma fresa redonda deixa seu raio em cada canto interno – uma peça de encaixe angular não entra. O alívio avança brevemente para o canto e volta em cada canto interno vivo.{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"Um agente conectado trabalha no projeto aberto: lê e altera a linha do tempo, consulta corpos, volumes e erros, obtém peças normalizadas do catálogo de peças, pede uma imagem da vista, exporta STEP ou STL, cria ferramentas e operações de fabricação e gera o programa NC, que ainda precisa ser verificado antes do primeiro corte. Ele não tem acesso a arquivos, preferências nem a outros projetos. Cada alteração é um passo que Ctrl+Z desfaz.",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"Um segundo clique no botão da ferramenta de desenho volta para Selecionar",
"Ein-/Ausblenden":"Mostrar/Ocultar",
"Ein-/Ausfahrten und Übergänge":"Entradas, saídas e transições",
"Einblenden":"Mostrar",
"Einblendungen":"Sobreposições",
"Eine .f3d-Datei ist ein geschlossenes Format – die Zeitachse darin kann kein anderes Programm lesen. Fusion selbst gibt sie aber über seine Skript-Schnittstelle heraus:":"Um arquivo .f3d é um formato fechado – nenhum outro programa consegue ler a linha do tempo dentro dele. O próprio Fusion, porém, a fornece por meio de sua interface de scripts:",
"Eine .ofab-Datei von diesem Computer öffnen":"Abrir um arquivo .ofab deste computador",
"Eine Bahn entlang jeder Innenecke/Hohlkehle, in der das Werkzeug zwei Flächen zugleich berührt – zum Ausräumen nach dem Schlichten.":"Uma trajetória ao longo de cada canto interno/rebaixo em que a ferramenta toca duas faces ao mesmo tempo – para limpeza após o acabamento.",
"Eine Bearbeitung anlegen, z. B. FRÄSEN → „2D-Kontur“ oder „Planfräsen“, Werkzeug wählen, OK.":"Criar uma operação, p. ex. FRESAMENTO → “Contorno 2D” ou “Faceamento”, escolher a ferramenta, OK.",
"Eine Bohrung setzen: „Bohrung“ (H), auf die Oberseite klicken, Durchmesser wählen, OK. (Eine Extrusion mit „Ausschneiden“ zählt auch.)":"Inserir um furo: “Furo” (H), clique na face superior, escolha o diâmetro, OK. (Uma extrusão com “Cortar” também conta.)",
"Eine Explosionsansicht braucht mindestens zwei Körper.":"Uma vista explodida precisa de pelo menos dois corpos.",
"Eine Explosionsansicht öffnen: „Explosionsansicht“ – „Montageanleitung“ macht daraus eine Seite mit Bildern.":"Abrir uma vista explodida: “Vista explodida” – “Instruções de montagem” gera uma página com imagens.",
"Eine Fläche, Bohrung oder einen Zapfen anklicken.":"Clique em uma face, furo ou pino.",
"Eine Fläche, Bohrung oder einen Zapfen eines Körpers anklicken.":"Clique em uma face, furo ou pino de um corpo.",
"Eine Konfiguration merkt sich die Ausdrücke aller Parameter unter einem Namen – etwa „kurz“ und „lang“. Ein Klick stellt die Variante wieder her.":"Uma configuração guarda as expressões de todos os parâmetros sob um nome – por exemplo “curto” e “longo”. Um clique restaura a variante.",
"Eine Platte mit Bohrung und abgerundeten Kanten – Skizze, Extrusion, Bohrung und Verrundung.":"Uma placa com furo e arestas arredondadas – esboço, extrusão, furo e concordância.",
"Eine STEP-, IGES-, STL-, OBJ-, 3MF- oder PLY-Datei in ein neues Design einfügen":"Inserir um arquivo STEP, IGES, STL, OBJ, 3MF ou PLY em um novo design",
