"Eine Seite mit einem Bild je Montageschritt (Explosion rückwärts), druckbar und als PDF":"Uma página com uma imagem por etapa de montagem (explosão em ordem inversa), imprimível e em PDF",
"Eine Variante speichern: VERWALTEN → „Konfigurieren“, Name z. B. dünn.":"Salvar uma variante: GERENCIAR → “Configurar”, nome p. ex. fina.",
