"Erzeugendes Feature in Zeitachse suchen":"Localizar na linha do tempo o recurso gerador",
"Erzeugt eine neue Fläche im Abstand zu den gewählten Flächen (negativ = nach innen). Der Körper bleibt unverändert.":"Cria uma nova superfície a uma distância das faces selecionadas (negativo = para dentro). O corpo permanece inalterado.",
"Erzeugt einen Tastzyklus (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).":"Gera um ciclo de apalpação (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).",
"Es braucht einen Körper – falls keiner da ist: Datei → Beispiele, oder zuerst „Erstes Teil“.":"É necessário um corpo – se não houver nenhum: Arquivo → Exemplos, ou primeiro “Primeira peça”.",
"Es braucht einen Körper – falls noch keiner da ist, zuerst die Aufgabe „Erstes Teil“ machen.":"É necessário um corpo – se ainda não houver nenhum, faça primeiro a lição “Primeira peça”.",
"Es braucht mindestens zwei Körper (z. B. zwei Extrusionen mit „Neuer Körper“).":"São necessários pelo menos dois corpos (p. ex. duas extrusões com “Novo corpo”).",
"Es würde nichts übrig bleiben":"Nada restaria",
