"Flächen wählen, die geneigt werden sollen (oder nicht mehr gefunden)":"Selecione as faces a inclinar (ou não foram mais encontradas)",
"Flächen wählen, die verschoben werden (bei einer Bohrung die Wand, bei einer Tasche Wände und Boden)":"Selecione as faces a mover (em um furo a parede, em uma cavidade as paredes e o fundo)",
"Flächen wählen, die verschwinden sollen":"Selecione as faces que devem desaparecer",
"Flächen wählen, die versetzt werden sollen":"Selecione as faces a serem deslocadas",
