"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Percorre todas as arestas externas vivas acessíveis por cima e as quebra pela profundidade de rebarbação – com a fresa de chanfrar como chanfro (eixo da ferramenta vertical, ponta fora da aresta), com a fresa esférica/lollipop arredondada.",
"Führungszapfen-Ø":"Ø do pino-guia",
"Für 2D-Fase einen Fasenfräser (V) wählen":"Selecione uma fresa de chanfro (V) para o chanfro 2D",
