"Für Dateien aus Programmen, in denen Y nach oben zeigt: das Netz wird aufgerichtet und auf Z = 0 gestellt":"Para arquivos de programas em que Y aponta para cima: a malha é endireitada e colocada em Z = 0",
"Für Gewindebohren einen Gewindebohrer wählen":"Selecione um macho de rosca para o roscamento",
"Für Gewindefräsen einen Gewindefräser wählen":"Selecione uma fresa de rosca para o fresamento de rosca",
"Für Setups, die nicht von oben bearbeitet werden":"Para setups que não são usinados por cima",
"Für Sweep wird ein Pfad gebraucht: offene Linie in einer Skizze (mit Enter beenden).":"O Sweep precisa de um caminho: uma linha aberta em um esboço (finalize com Enter).",
"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"Para touchpads: rolar desloca a vista, o gesto de pinça (ou Ctrl + roda do mouse) dá zoom",
"Für V-Gravur einen Fasenfräser (V) wählen":"Selecione uma fresa de chanfro (V) para a gravação em V",
"Für den Steuerungszyklus entlang einer Linie die Nutbreite angeben":"Para o ciclo do comando ao longo de uma linha, indique a largura do rasgo",
"Für diese Strategie nicht geeignet":"Não adequado para esta estratégia",
"Für eine Bohrung Ø {0} mm gibt es in dieser Reihe keine passende Schraube.":"Para um furo Ø {0} mm não há parafuso adequado nesta série.",
"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"Para direções oblíquas, crie um eixo de construção (por dois pontos, um cilindro ou dois planos) – ele aparece aqui como direção.",
"Für wirbelndes Fräsen entlang einer Linie die Nutbreite angeben":"Para fresamento trocoidal ao longo de uma linha, informe a largura do rasgo",
"Für {0} ist kein Gewinde hinterlegt.":"Não há rosca definida para {0}.",
"Für {0} ist keine Durchgangsbohrung hinterlegt":"Não há furo passante definido para {0}",
"Für „Bild“: füllt die Ansicht hinter dem Modell":"Para “Imagem”: preenche a vista atrás do modelo",
