"GRBL 1.1 steuert nur X, Y und Z: Für die Drehachse A braucht es eine 4-Achs-Variante (z. B. grblHAL) – sonst bleibt das Programm am ersten A-Wort stehen":"O GRBL 1.1 controla apenas X, Y e Z: o eixo rotativo A exige uma variante de 4 eixos (p. ex. grblHAL) – caso contrário o programa para na primeira palavra A",
"GRBL-Laser (M4, Leistung folgt dem Vorschub)":"Laser GRBL (M4, a potência acompanha o avanço)",
