"Gefräst wird von unten nach oben im Gleichlauf. M6 = Nenn-Ø 6, Steigung 1; M8 = 8 / 1,25; M10 = 10 / 1,5.":"O fresamento é feito de baixo para cima em corte concordante. M6 = Ø nominal 6, passo 1; M8 = 8 / 1,25; M10 = 10 / 1,5.",
"Gegenlauf":"Discordante",
"Gekrümmte Flächen":"Faces curvas",
