"Gelenk":"Junta",
"Gelenk: 1. Komponente (wird bewegt) – Bohrung, Zapfen oder Fläche anklicken.":"Junta: 1º componente (será movido) – clique em um furo, pino ou face.",
"Gelenk: 2. Komponente (Bezug) – Bohrung, Zapfen oder Fläche anklicken.":"Junta: 2º componente (referência) – clique em um furo, pino ou face.",
