"Gelenkursprung: Bohrung, Zapfen oder Fläche anklicken (mehrere nacheinander möglich).":"Origem da junta: clique em um furo, pino ou face (vários em sequência são possíveis).",
"Gelenkursprünge ({0})":"Origens de junta ({0})",
"Gelenkursprünge neu wählen":"Selecionar origens da junta novamente",
"Gemeinsame Schnittkanten nur einmal schneiden":"Cortar as arestas de corte comuns apenas uma vez",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Arestas de corte comuns: se duas peças recortadas estiverem separadas exatamente por uma largura de corte (ao aninhar, informe a largura de corte como distância), suas trajetórias coincidem na aresta comum e ela é cortada apenas uma vez. A entrada de corte nunca fica em uma peça vizinha: se ao lado de um contorno não houver sobra livre, a perfuração é feita sobre o contorno. Após “Pré-visualização”, uma imagem por chapa-base mostra a trajetória antes de os arquivos serem salvos.",
"Genauigkeit":"Precisão",
"Geodätische Linie":"Linha geodésica",
