"Geometriekern nicht geladen":"Kernel geométrico não carregado",
"Geometriekern: OpenCascade (über replicad) · Darstellung: three.js · Einstellungen werden auf diesem Rechner gespeichert.":"Kernel geométrico: OpenCascade (via replicad) · Renderização: three.js · As configurações são salvas neste computador.",
