"Geschafft! Das Teil steht in der Zeitleiste unten – ein Doppelklick auf einen Schritt ändert ihn nachträglich. Weiter geht es mit „Maße als Parameter“ oder „Vom Teil zum NC-Programm“.":"Pronto! A peça está na linha do tempo embaixo – um clique duplo em uma etapa permite editá-la depois. Continue com “Cotas como parâmetros” ou “Da peça ao programa NC”.",
"Geschlossen":"Fechado",
"Geschlossen (Gehrung)":"Fechado (esquadria)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Fechado: as abas em duas arestas vizinhas vão até a bissetriz do canto e deixam a folga ali. O alívio de canto fica onde as zonas de dobra se cruzam – na planificação e na peça dobrada. Uma aba em uma aresta curva também é cortada em meia-esquadria em um canto real (ali sem alívio de canto).",
"Geschlossene Kette {0}":"Cadeia fechada {0}",
"Geschlossene Profile begrenzen den Bereich.":"Perfis fechados delimitam a área.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Preencher com cor os perfis fechados do esboço ativo",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Perfis fechados viram superfícies planas – p. ex. tampa e fundo, para depois costurar as superfícies em um corpo.",
"Geschnitten ab X":"Cortado a partir de X",
"Geschwenkte Bearbeitungsebene":"Plano de usinagem inclinado",
"Geschwindigkeit der Animation":"Velocidade da animação",
"Geschätzte Bearbeitungszeit (Klick: Details)":"Tempo de usinagem estimado (clique: detalhes)",
"Gesicherte Vorgaben laden":"Carregar padrões salvos",
"Gespeichert unter neuem Namen":"Salvo com novo nome",
"Gespeichert werden Blechdicke {0} mm, Biegeradius innen {1} mm und K-Faktor {2}. Die Regel steht danach bei jedem Blech in der Liste „Blechregel“ – auch in anderen Projekten auf diesem Rechner.":"São salvos a espessura da chapa {0} mm, o raio de dobra interno {1} mm e o fator K {2}. Depois a regra aparece na lista “Regra de chapa” de cada chapa, também em outros projetos neste computador.",
"Gespiegelt":"Espelhado",
"Gestrichelt im DXF/der Skizze: Biegelinien (Anfang und Ende jeder Biegezone). Im DXF liegen sie auf der Ebene BIEGUNG, der Umriss auf Ebene 0.":"Tracejadas no DXF/esboço: linhas de dobra (início e fim de cada zona de dobra). No DXF ficam na camada BIEGUNG e o contorno na camada 0.",
