"Gewinde als ein Zyklus-Satz: Okuma G71 (gerade Zustellung B0, Gewindetiefe H, erste Zustellung D), Fanuc G76 (Flankenzustellung 60°).":"Rosca como um único bloco de ciclo: Okuma G71 (penetração reta B0, profundidade da rosca H, primeira penetração D), Fanuc G76 (penetração pelo flanco 60°).",
"Gewinde auf eine Zylinderfläche oder in eine Bohrung legen":"Aplicar uma rosca numa face cilíndrica ou num furo",
"Gewinde braucht einen Körper mit Bohrung oder Bolzen.":"Rosca precisa de um corpo com furo ou pino.",
"Gewinde in mehreren Schnitten drehen":"Tornear uma rosca em várias passagens",
