"Gewindebohrung für {0} – Skizze":"Furo roscado para {0} – esboço",
"Gewindebohrung im untersten Teil":"Furo roscado na peça inferior",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Furo roscado na peça mais baixa: o furo passante termina onde começa a peça mais baixa; ali é criado o furo de núcleo com rosca, três passos de rosca mais fundo do que o parafuso alcança, ou através de toda a peça. Se apenas uma peça estiver abaixo do ponto, ela recebe a rosca a partir da sua face. “Comprimento adequado à profundidade de rosqueamento” escolhe o próximo comprimento da série com o qual o parafuso fica rosqueado aproximadamente tanto quanto a espessura da sua rosca (valor de referência para aço), mas nunca mais longo do que a espessura da peça.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"furo roscado {0} – profundidade de rosqueamento de apenas {1} mm",
"Gewindebohrung {0}, Einschraubtiefe {1} mm":"furo roscado {0}, profundidade de rosqueamento {1} mm",
"Gewindebohrung: gebohrt wird das Kernloch; das Gewinde erscheint als Gewindedarstellung am Modell und mit seinem Namen in der Zeichnung.":"Furo roscado: é feito o furo de núcleo; a rosca aparece como representação de rosca no modelo e com o seu nome no desenho.",
