"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Diâmetros iguais resultam em um tubo, diâmetros diferentes em um tronco de cone. A planificação é calculada na linha neutra (face interna + fator K × espessura da chapa); na calandragem ela fica mais próxima do centro da chapa do que na dobra – um fator K de 0,45 a 0,5 é usual. Com uma regra de chapa valem a espessura e o fator K dela. A folga da junta permanece aberta no diâmetro maior (0 = topo a topo, no corpo então uma fenda de 0,01 mm).",
"Gleiche Länge oder gleichen Radius erzwingen":"Forçar comprimento igual ou raio igual",
"Gleicher Abstand":"Distância igual",
"Gleichlauf":"Concordante",
"Gleichmäßige Dreiecke dieser Größe: lange Kanten werden geteilt, danach wird auf die Dreieckszahl eines gleichmäßigen Netzes reduziert. Gut vor dem Glätten oder Formen von Scans.":"Triângulos uniformes deste tamanho: arestas longas são divididas e, depois, a malha é reduzida ao número de triângulos de uma malha uniforme. Útil antes de suavizar ou modelar escaneamentos.",
