"Halbzeug: Nennmaße der Norm, auf jede Länge zugeschnitten. Nicht jede Paarung von Maß und Wanddicke ist bei jedem Händler am Lager. Ein Rohr entlang einer Skizzenlinie – auch um Ecken und Bögen – legt der Befehl „Rohr“ an.":"Semiacabado: medidas nominais da norma, cortado em qualquer comprimento. Nem toda combinação de medida e espessura de parede está em estoque em todo fornecedor. Um tubo ao longo de uma linha de esboço – também em torno de cantos e arcos – é criado pelo comando “Tubo”.",
