"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: habilitar no comando a transferência de dados por Ethernet (como para TNCremo, LSV2, porta 19000); pasta padrão TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: porta 21, pasta p. ex. /_N_WKS_DIR ou /NC. Pasta de rede: caminho como \\\\MASCHINE\\NC ou Z:\\NC. DNC: conversor como servidor TCP (raw), geralmente porta 4001; no comando iniciar “Execução externa”, DNC ou TAPE.",
