"Im Programm: die Designs liegen im Speicher des Programms auf diesem Computer. Ordner: jedes Design liegt zusätzlich als .ofab-Datei in einem Ordner Ihrer Wahl, z. B. auf einem Netzlaufwerk oder in einem synchronisierten Ordner. Die gespeicherten Versionen bleiben im Programm.":"No programa: os designs ficam na memória do programa neste computador. Pasta: cada design fica também como arquivo .ofab numa pasta à sua escolha, por exemplo numa unidade de rede ou numa pasta sincronizada. As versões salvas permanecem no programa.",
"Im Setup gewählt, bestimmt die Maschine Postprozessor, Eilgang (Laufzeit) und die Grenzwert-Prüfungen.":"Quando selecionada no setup, a máquina define o pós-processador, o avanço rápido (tempo de execução) e as verificações de limites.",
"Im Spiegelbild läuft das Werkzeug andersherum: aus Gleichlauf wird dort Gegenlauf. Die Radiuskorrektur der Steuerung wechselt die Seite mit.":"Na imagem espelhada, a ferramenta percorre o sentido inverso: o corte concordante torna-se discordante ali. A compensação de raio do comando também troca de lado.",
