"In „{0}“ wurden keine Bohrungen gefunden (gesucht: runde Durchgangs- und Sacklöcher, auch mit Senkung). Bei Netzen vorher „Netz → Körper“ – dort werden Bohrungen zu echten Zylindern.":"Nenhum furo foi encontrado em “{0}” (procurados: furos redondos passantes e cegos, também com rebaixo). Em malhas, use antes “Malha → corpo” – ali os furos se tornam cilindros reais.",
