"JSON kopieren":"Copiar JSON",
"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"Dois parâmetros Q por operação no início do programa: o primeiro desloca a profundidade (DL, + = menos profundo), o segundo o sobremetal lateral (DR, + = mais sobremetal; só funciona com compensação de raio no comando RL/RR). Na máquina, altere um número em vez de procurar blocos.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"A primeira curva de cada esboço – aberta ou fechada. As curvas são unidas por uma pele (superfície sem espessura).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Um arquivo por chapa-base. A trajetória corre ao lado do contorno, na sobra, afastada em meia largura de corte (no fresamento, meia fresa); os recortes vêm antes do contorno da sua peça e cada contorno começa com uma entrada de corte a partir da sobra. As fendas de veneziana são cortadas sobre a sua linha. Pontes de fixação: esta quantidade de pontos por contorno permanece sem corte (laser, plasma, jato d'água: o feixe é interrompido ali; fresamento: a fresa sobe até metade da espessura da chapa); contornos com menos de 40 mm de comprimento não recebem nenhuma. “Comando” define como o feixe é ligado e desligado; o tempo de perfuração aparece como G4 no programa, a menos que o comando perfure por conta própria. A origem é o canto inferior esquerdo da chapa-base; no fresamento, Z0 é a face superior da chapa. Verifique o programa na máquina ou em um simulador NC antes de usá-lo.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"Todas as peças por ferramenta (menos trocas de ferramenta)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Cada eixo separadamente: clique em uma aresta, canto, face ou furo. Eixos não definidos vêm do ponto do bruto.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Cada furo é abordado individualmente com as suas coordenadas (X/Y por furo) – sem padrão de círculo de furos nem grelha.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Cada operação como subprograma (LBL) no fim do programa, chamada com CALL LBL",
"Jede Variante berechnen und als STEP, STL oder 3MF speichern (eine ZIP-Datei)":"Calcular cada variante e salvá-la como STEP, STL ou 3MF (um arquivo ZIP)",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Cada círculo do esboço é o centro de um furo. A furação é feita contra a normal do esboço (para dentro do material).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Cada círculo do esboço é repetido girando em torno do centro (em coordenadas do esboço) – um círculo à distância do raio do círculo primitivo resulta em um círculo de furos.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Cada círculo do esboço se torna uma grade: espaçamentos em X e Y do esboço (também negativos).",
"Jeder Schritt ist gegen Volumen, Körperzahl und Schwerpunkt aus Fusion geprüft. Skizzen kommen mit festen Maßen, ohne Abhängigkeiten.":"Cada etapa é verificada em relação ao volume, ao número de corpos e ao centro de massa do Fusion. Os esboços vêm com cotas fixas, sem restrições.",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Cada corpo visível se torna um elo (link) com malha (STL, em metros), massa e inércia, e cada junta se torna uma junta (joint) com eixo e limites. A posição atual é a posição zero. Com um nome de pacote, as malhas aparecem no URDF como package://Name/meshes/…; caso contrário, como caminho relativo.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Cada # no texto do esboço é substituído pelo número, completado com zeros (SN-#### → SN-{0}). Com várias peças em uma fixação, cada peça recebe o próximo número: {1}{2}.",
"Jedes Design liegt als .ofab-Datei im Ordner und wird nach jeder Änderung neu geschrieben. Dateien, die dort hineinkopiert werden, erscheinen hier.":"Cada design é um arquivo .ofab na pasta e é regravado a cada alteração. Arquivos copiados para lá aparecem aqui.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Cada peça tem sua própria origem no comando (G54, G55 … ou número do ponto de referência na tabela – ciclo Heidenhain 247). Defina todas as origens na máquina antes.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Cada dimensão própria e cada quadro de tolerância recebe um número em um círculo. A lista contém dimensão nominal, tolerância, dimensão máxima e mínima e campos para o valor real. Dimensões sem tolerância própria recebem a tolerância geral.",
"Jetzigen Stand festhalten":"Salvar o estado atual",
