"Kugel-, Schaft-, Torus- oder Konusfräser. Ein Kugelfräser behält seine Bahn; andere Fräser werden geneigt und entlang ihrer Achse verschoben, bis sie am Teil anliegen, ohne es zu verletzen. Höchstens die größte Neigung; wo Schaft oder Halter das Teil berühren würden, richtet sich das Werkzeug auf. Ausgabe als Werkzeugvektor (Heidenhain, Sinumerik, Fanuc), sonst als 3-Achs-Bahn.":"Fresa de ponta esférica, de topo reto, toroidal ou cónica. Uma fresa de ponta esférica mantém a sua trajetória; as outras fresas são inclinadas e deslocadas ao longo do eixo até encostarem à peça sem a danificar. No máximo até à inclinação máxima; onde a haste ou o porta-ferramentas tocariam na peça, a ferramenta endireita-se. Saída como vetor da ferramenta (Heidenhain, Sinumerik, Fanuc), caso contrário como trajetória de 3 eixos.",
