"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Aba sobre aba: um ângulo + continua dobrando na mesma direção (perfil em U, dobra de 180°), − na direção oposta (degrau em Z, perfil chapéu). Bainha: a borda da aba é dobrada 180° sobre si mesma – aberta com uma folga de uma espessura de chapa, fechada comprimida até ficar plana; com − 180° ela fica do outro lado. O campo R é o raio interno apenas desta dobra (vazio = como na chapa). Para uma bainha diretamente na aresta da placa, ajuste a própria aba para 180°. Desnível: duas dobras em sentidos opostos (− 45° e + 45°) – a borda continua paralela, deslocada; o deslocamento resulta do comprimento do trecho inclinado e dos ângulos.",
"Lasche {0}":"Aba {0}",
"Laschen, die über eine Biegelinie laufen, sind dort geteilt und freigestellt.":"Abas que cruzam uma linha de dobra são divididas e liberadas ali.",
