"Länge L ist die Messlänge aus dem Werkzeug (Nennwert). Die echten Längen an der Maschine oder am Voreinstellgerät messen und eintragen. Heidenhain: Datei nach TNC:\\system\\tooltab kopieren, dann Werkzeugverwaltung → WERKZEUG IMPORT.":"O comprimento L é o comprimento de medição da ferramenta (valor nominal). Meça os comprimentos reais na máquina ou no presetter e insira-os. Heidenhain: copie o arquivo para TNC:\\system\\tooltab, depois gerenciamento de ferramentas → TOOL IMPORT.",
