"Macht ein geschlossenes Netz hohl: eine Innenwand im Abstand der Wandstärke kommt dazu – spart Material und Druckzeit. Stellen, die dünner sind als zwei Wandstärken, überschneiden sich danach; für Harzdruck ein Ablaufloch mit „Boolesch“ abziehen.":"Torna oca uma malha fechada: é adicionada uma parede interna na distância da espessura de parede – economiza material e tempo de impressão. Pontos mais finos que duas espessuras de parede se sobrepõem depois; para impressão com resina, subtraia um furo de drenagem com “Booleana”.",
