"Mehrere Schlichtdurchgänge":"Várias passadas de acabamento",
"Mehrere Schrupp- oder Schlichtdurchgänge gibt es nur als Bahn":"Várias passadas de desbaste ou acabamento só existem como trajetória",
"Mehrere Teile in einer Aufspannung":"Várias peças em uma fixação",
"Mehrere Zustellungen und Leerdurchgang gibt es nur als Bahn":"Várias profundidades de corte e a passada em vazio só existem como trajetória",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Várias arestas encadeadas contam como um único trecho: o raio vai do início da cadeia até o seu fim, e os pontos de controle valem em % do comprimento total da cadeia. Isto é calculado pelo núcleo geométrico completo.",
"Mehrfachaufspannung":"Várias peças",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"Várias peças: este comando não tem origem para a peça {0} – só uma peça gerada",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Várias peças: este pós-processador não tem deslocamento de origem – escolha “Origem própria por peça”; só uma peça gerada",
"Meine Designs · {0}":"Meus designs · {0}",
"Meine Werkzeuge":"Minhas ferramentas",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Avisa sobre trajetórias que cortam mais fundo que o modelo neste ponto (fresas de topo, de facear, esféricas e toroidais, fresas de chanfro e brocas com seu cone; movimentos de 3 eixos). Um corte que não está no modelo – gravação, alívio de canto, bolsão feito apenas a partir de um esboço – também é avisado.",
"Meldung auf dem Bildschirm der Steuerung: Fanuc und LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), sonst als Kommentar.":"Mensagem na tela do comando: Fanuc e LinuxCNC como (MSG, …), Sinumerik como MSG(\"…\"), caso contrário como comentário.",
