"Prägung":"Relevo",
"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"Relevo {0}: o contorno é mais estreito que 2 × a espessura da chapa – não sobra cavidade.",
"Prägung {0}: lässt sich so nicht formen":"Relevo {0}: não pode ser conformado assim",
