"Schraubstock: die Backen greifen quer zur X-Achse des Setups (an Y-min und Y-max des Rohteils); 0 = Größe und Spanntiefe passend wählen. Die Spannmittel werden einfache Körper am Ende der Zeitleiste und hier als Spannmittel eingetragen: Halter- und Kollisionsprüfung, Sicherheitsabstände und Einrichteblatt berücksichtigen sie.":"Morsa: os mordentes fixam transversalmente ao eixo X do setup (em Y-mín e Y-máx do bruto); 0 = escolher tamanho e profundidade de fixação automaticamente. Os dispositivos de fixação tornam-se corpos simples no fim da linha do tempo e são registrados aqui como dispositivos de fixação: a verificação de porta-ferramenta e de colisões, as distâncias de segurança e a folha de setup os consideram.",
