"Tauchschruppen: senkrechte Tauchgänge Reihe für Reihe – für lange Werkzeuge und tiefe Kavitäten":"Desbaste por mergulho: mergulhos verticais fileira por fileira – para ferramentas longas e cavidades profundas",
"Teil 1 liegt normalerweise auf dem Nullpunkt (0, 0, 0). Die anderen werden mit einer Nullpunktverschiebung angefahren (Heidenhain Zyklus 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Vor jedem Wechsel geht das Werkzeug auf die sichere Höhe.":"A peça 1 fica normalmente na origem (0, 0, 0). As outras são alcançadas com um deslocamento de origem (ciclo Heidenhain 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Antes de cada troca a ferramenta vai para a altura segura.",
