"Teilt Kanten, die länger sind, in der Mitte (je Durchgang einmal) – die Form bleibt gleich. 0 teilt jede Kante: jedes Dreieck wird zu vier. Sinnvoll vor dem Glätten grober Netze.":"Divide ao meio as arestas mais longas (uma vez por passada) – a forma permanece a mesma. 0 divide todas as arestas: cada triângulo vira quatro. Útil antes de suavizar malhas grosseiras.",
