"Verschiebt jede Fläche um den Abstand nach außen (negativ: nach innen) – für Spiel, Aufmaß oder ein Negativ. Kanten und Ecken bleiben scharf; sehr feine Stellen können sich beim Schrumpfen überschneiden.":"Desloca cada face para fora pela distância indicada (negativa: para dentro) – para folga, sobremetal ou um negativo. Arestas e cantos permanecem vivos; detalhes muito finos podem se sobrepor ao encolher.",
