"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"União parafusada: as arruelas e a porca são colocadas junto com o parafuso, de uma só vez, em cada furo clicado. A espessura fixada é o comprimento do furo – através de várias peças, se seus furos estiverem alinhados e encostados. Com porca, é sugerido o menor comprimento preferencial com que o parafuso sobressai dois filetes da porca.",
