"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"Com que finura os corpos são divididos em triângulos para STL, 3MF e o Slicer: desvio em relação à superfície real como fração do tamanho do corpo. As malhas permanecem como estão.",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Quão finamente cilindros, esferas e concordâncias são formados por triângulos na vista. Mais fino parece mais redondo, mas demora mais em modelos grandes. A exportação tem uma configuração própria (impressão 3D).",
"Wie im System":"Como no sistema",
