"Zahnform nach Tredgold (Ersatz-Stirnrad auf dem Rückenkegel), gerade Zähne. Das große Ende liegt in der Grundebene, die Zähne laufen zur Kegelspitze. Für Darstellung, 3D-Druck und Fräsen aus dem Vollen; geschliffene Kegelräder brauchen die Daten des Herstellers.":"Perfil do dente segundo Tredgold (engrenagem cilíndrica equivalente sobre o cone complementar), dentes retos. A extremidade maior fica no plano de base, os dentes correm em direção ao vértice do cone. Para visualização, impressão 3D e fresamento a partir do maciço; engrenagens cônicas retificadas precisam dos dados do fabricante.",
"Zahnrad: Stirnrad gerade / schräg / Pfeil, Hohlrad, Zahnstange, Kegelrad, Schnecke, Schneckenrad, Kettenrad":"Engrenagem: cilíndrica de dentes retos / helicoidais / espinha de peixe, engrenagem interna, cremalheira, engrenagem cônica, sem-fim, coroa sem-fim, roda dentada para corrente",
