"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"As linguetas sobressaem na extremidade livre da aba e entram no blank. “Rasgos como esboço” cria os rasgos correspondentes onde estão as linguetas – um esboço por plano, com cada rasgo maior que a lingueta pela folga em todo o contorno. Desenhe neste esboço o contorno da peça correspondente e crie a partir dele uma chapa ou uma extrusão: os rasgos viram recortes. A peça correspondente apoia-se nas extremidades das abas; o comprimento das linguetas costuma ser igual à sua espessura.",
