"Zwischen zwei Schnitten hebt das Werkzeug nur so weit ab, wie das Material auf dem Weg es verlangt (Rohteil abzüglich allem, was dieses Setup bis dahin gefräst hat) plus Sicherheitsabstand – und beginnt den Vorschub erst dort.{0}{1}":"Entre dois cortes, a ferramenta só sobe o quanto o material no caminho exige (bruto menos tudo o que este setup já fresou até ali) mais a distância de segurança – e só começa o avanço ali.{0}{1}",
