"{0}: 5-Achs-Simultan wird von diesem Postprozessor{1} nicht ausgegeben – als 3-Achs-Bahn mit senkrechtem Werkzeug geschrieben (gleiche Fläche, da Kugelfräser)":"{0}: 5 eixos simultâneos não é emitido por este pós-processador{1} – gravado como trajetória de 3 eixos com a ferramenta na vertical (mesma superfície, por ser fresa esférica)",
