"{0}: Fläche oder Kante im Modell anklicken.":"{0}: clique em uma face ou aresta no modelo.",
"{0}: GRBL kennt keine Radiuskorrektur (G41/G42) – Bahn ohne Korrektur ausgegeben":"{0}: O GRBL não possui compensação de raio (G41/G42) – trajetória gerada sem compensação",
"{0}: Neigung bis {1}° – die Schwenkachse der Maschine reicht nur bis {2}°":"{0}: inclinação de até {1}° – o eixo basculante da máquina só alcança {2}°",
"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0}: A origem da peça Y/Z não está no eixo de rotação A (eixo em Y{1} Z{2}) – para 4 eixos simultâneos, coloque a origem da peça no eixo (ponto do bruto centro Y/Z)",
"{0}: Postprozessor ohne Drehzyklus – als Bahn ausgegeben":"{0}: Pós-processador sem ciclo de torneamento – emitido como trajetória",
"{0}: Postprozessor ohne Polar-Interpolation – Flächen als kurze X/C-Schritte (C in Grad) ausgegeben; der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Polar-Interpolation ein/aus“ eintragen":"{0}: Pós-processador sem interpolação polar – faces geradas como pequenos passos X/C (C em graus); dependendo do comando, o avanço então não vale ao longo da trajetória. É melhor preencher o modelo „Interpolação polar ligada/desligada“",
"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: Pós-processador sem o modelo “Eixo C e ferramenta motorizada ligados” – ligue o eixo C e o fuso da ferramenta manualmente",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: Pós-processador sem interpolação cilíndrica – Z e C se movem juntos; dependendo do comando, o avanço então não vale ao longo da trajetória. É melhor preencher o modelo „Interpolação cilíndrica ligada/desligada“",
